import sys, importlib.abc, importlib.util, json
class Block(importlib.abc.MetaPathFinder):
 def find_spec(self,fullname,path=None,target=None):
  if fullname.split('.')[0] in {'torch','torch_neuronx','torch_xla','numpy','neuronxcc','neuronx_distributed','neuronx_distributed_inference','vllm','transformers'}:raise AssertionError('native import denied: '+fullname)
sys.meta_path.insert(0,Block())
import vllm_neuron
result={'origin':vllm_neuron.__file__,'path':list(vllm_neuron.__path__),'sys_path':sys.path,'models_found':False}
spec=importlib.util.find_spec('vllm_neuron.models')
if spec is not None:
 result['models_found']=True
 from vllm_neuron.models.qwen35 import prepare_view
 result['prepare_view_source']=prepare_view.__file__
result['native_imported']=[n for n in sys.modules if n.split('.')[0] in {'torch','torch_neuronx','numpy','neuronxcc','vllm','transformers'}]
print(json.dumps(result))
